 * Retry helper with bounded exponential backoff, cancellation, and error propagation.
 */

interface RetryOptions {
  /** Maximum number of retry attempts (default: 3) */
  maxRetries?: number;
  /** Initial delay in milliseconds (default: 100) */
  initialDelayMs?: number;
  /** Maximum delay in milliseconds (default: 5000) */
  maxDelayMs?: number;
  /** Backoff multiplier (default: 2) */
  backoffMultiplier?: number;
  /** Optional cancellation token */
  signal?: AbortSignal;
}

interface RetryResult<T> {
  success: true;
  value: T;
  attempts: number;
}

interface RetryFailure<T> {
  success: false;
  error: Error;
  attempts: number;
}

type RetryOutcome<T> = RetryResult<T> | RetryFailure<T>;

/**
 * Creates a bounded exponential backoff delay in milliseconds.
 */
function calculateBackoff(
  attempt: number,
  initialDelayMs: number,
  maxDelayMs: number,
  backoffMultiplier: number
): number {
  const delay = initialDelayMs * Math.pow(backoffMultiplier, attempt);
  return Math.min(delay, maxDelayMs);
}

/**
 * Sleeps for the specified number of milliseconds.
 * Returns a promise that resolves after the delay.
 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

